def solve_math_problem(
    celsius_value: float,
    c_freeze: float,
    c_boil: float,
    s_freeze: float,
    s_boil: float
) -> float:
    """
    Calculates the temperature on a linear scale given a Celsius value.

    Formula: S = S_freeze + (C - C_freeze) * (S_boil - S_freeze) / (C_boil - C_freeze)
    """
    if c_boil == c_freeze:
        raise ValueError("Celsius boiling and freezing points must be different.")

    try:
        slope = (s_boil - s_freeze) / (c_boil - c_freeze)
        samo_value = s_freeze + (celsius_value - c_freeze) * slope
        return float(samo_value)
    except ZeroDivisionError:
        raise ValueError("Division by zero occurred during calculation.")

